def is_prime(number):
    if number < 2:
        return False
    for i in range(2, int(number ** 0.5) + 1):
        if number % i == 0:
            return False
    return True

def prime_fib():
    fib_sequence = [0, 1]

    while True:
        next_fib = fib_sequence[-2] + fib_sequence[-1] # Generate the nth Fibonacci number in sequence.

        if is_prime(next_fib):
            return next_fib  # Return prime Fibonacci number found at this point of time (in terms of iteration).

        fib_sequence.append(next_fib) # Add the new element to our sequence list for further checks in upcoming iterations.

# Testing: Get first few numbers that are both a part of Fibonacci series and prime number till 50th position (1-indexed).
for i in range(6):
    print(f"prime_fib({i+1}): {prime_fib()}")
```
